/**
 * Every connection handed to JPA/JDBC first gets
 * {@code SET @app_actor = ?, @request_id = ?} so the schema's audit triggers (17_audit_triggers.sql)
 * and version triggers (18_version_triggers.sql) record the authenticated Keycloak user and the
 * HTTP request id instead of the pooled database account.
 * A transaction borrows one connection, so the values are fixed for the whole transaction.
 */
public class ActorAwareDataSource extends DelegatingDataSource {

    private static final String SET_SESSION_VARS = "SET @app_actor = ?, @request_id = ?";

    public ActorAwareDataSource(DataSource targetDataSource) {
        super(targetDataSource);
    }

    @Override
    public Connection getConnection() throws SQLException {
        return tag(super.getConnection());
    }

    @Override
    public Connection getConnection(String username, String password) throws SQLException {
        return tag(super.getConnection(username, password));
    }

    private Connection tag(Connection connection) throws SQLException {
        try (PreparedStatement statement = connection.prepareStatement(SET_SESSION_VARS)) {
            statement.setString(1, ActorContext.currentActor());
            statement.setString(2, ActorContext.currentRequestId());
            statement.execute();
            return connection;
        } catch (SQLException ex) {
            connection.close();
            throw ex;
        }
    }
}
